corrected_code:
from sqlalchemy import text

@router.get("/catalog/schemas/{schema_id}/indexes")
async def get_schema_indexes(
    schema_id: str,
    db: AsyncSession = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    if schema_id not in current_user.accessible_schemas and not current_user.is_catalog_admin:
        raise HTTPException(status_code=403, detail="Forbidden: access to specified schema catalog denied")

    stmt = text(
        "SELECT indexname, tablename, indexdef "
        "FROM pg_indexes WHERE schemaname = :schema_name"
    ).bindparams(schema_name=schema_id)
    result = await db.execute(stmt)
    return {"schema": schema_id, "indexes": [dict(r._mapping) for r in result]}
